import{_ as a,o as e,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"全栈集成总览","description":"","frontmatter":{"title":"全栈集成总览"},"headers":[],"relativePath":"ts-ai/integration/index.md","filePath":"ts-ai/integration/index.md","lastUpdated":1786083160000}'),r={name:"ts-ai/integration/index.md"};function i(o,t,d,l,c,p){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="全栈集成总览" tabindex="-1">全栈集成总览 <a class="header-anchor" href="#全栈集成总览" aria-label="Permalink to &quot;全栈集成总览&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>把已经会跑的 Agent / Nest /（可选）RAG·工作流，接到<strong>可交付的前端交互</strong>：协议契约 → 体验原则 → <strong>Nuxt 主线实现</strong>。React / Next.js 整组是<strong>扩展</strong>，不是主线前置。</p><p>前置：<a href="/ts-ai/backend/">服务端工程</a>（至少 REST/SSE 与 Run 模型）；<a href="/ts-ai/agent/">Agent 开发</a> 能产出可观察轨迹更佳。</p><p><strong>怎么读：</strong></p><ol><li>先读 <a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">Message、Run 与 Tool Call 事件</a>（事件契约）</li><li>扫一眼 <a href="/ts-ai/integration/ai-interaction/streaming-state-feedback">流式状态与反馈</a>（状态机）</li><li>立刻跑 <a href="/ts-ai/integration/vue-nuxt/minimal-ai-chat-ui">最小可运行 AI Chat UI</a>（假事件流，无真模型）</li><li>再按 Nuxt 必学路径对接 Nest SSE</li><li><strong>React / Next 整组可选</strong>；仅在团队选型或迁移时再读</li><li>最后用 <a href="/ts-ai/integration/assembly/assembly-recipes-checklist">组装配方与自检</a> 收束</li></ol><h2 id="分组地图" tabindex="-1">分组地图 <a class="header-anchor" href="#分组地图" aria-label="Permalink to &quot;分组地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>你在学什么</th><th>优先级</th></tr></thead><tbody><tr><td><a href="/ts-ai/integration/interaction-protocols/">交互协议</a></td><td>事件模型、传输选型、解析、取消重连、鉴权/文件/错误契约</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/integration/ai-interaction/">AI 交互设计</a></td><td>信息架构、流式反馈、引用、工具确认、长任务、无障碍（框架无关）</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/integration/vue-nuxt/">Vue 3 与 Nuxt</a></td><td>Composable、状态、渲染、对接 Nest、完整 Chat（<strong>主线</strong>）</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/integration/react-next/">React 与 Next.js 扩展</a></td><td>选型、对照、Hooks、App Router、SDK、迁移</td><td><strong>扩展（非主线）</strong></td></tr><tr><td><a href="/ts-ai/integration/assembly/assembly-recipes-checklist">组装配方与能力自检</a></td><td>场景配方与跨组勾选</td><td><strong>必学</strong>（模块末）</td></tr></tbody></table><h2 id="跨章所有权" tabindex="-1">跨章所有权 <a class="header-anchor" href="#跨章所有权" aria-label="Permalink to &quot;跨章所有权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>本模块讲</th><th>别章讲</th></tr></thead><tbody><tr><td>SSE / WebSocket</td><td>事件形状、客户端解析、重连游标、去重</td><td><a href="/ts-ai/backend/api-realtime/sse-streaming">SSE 流式响应</a> 服务端推流实现</td></tr><tr><td>鉴权 Token / Cookie</td><td>前端携带方式与协议错误码</td><td><a href="/ts-ai/quality/security-governance/authentication-authorization">认证与授权</a>；Nest Guard</td></tr><tr><td>Thread / Run / Message</td><td>前端状态机与协议字段</td><td>表结构 → <a href="/ts-ai/backend/data-tasks/thread-run-message-model">data-tasks</a></td></tr><tr><td>文件上传 UI</td><td>上传→索引状态展示与重试</td><td><a href="/ts-ai/backend/api-realtime/file-upload">文件上传</a>；<a href="/ts-ai/knowledge/document-processing/ingestion-pipeline">Ingestion</a></td></tr><tr><td>工具确认 / HITL</td><td>确认 UX、参数展示、审计展示</td><td>图内 Interrupt → <a href="/ts-ai/workflow/durable-execution/interrupt-command">workflow</a>；Tool ACL → agent/quality</td></tr><tr><td>AI SDK（Vue/Vercel）</td><td>与<strong>自建 Nest 协议</strong>的映射与适配成本</td><td>不替代本手册默认 SSE/事件契约</td></tr></tbody></table><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>交互协议（事件 + 传输 + 取消重连）</span></span>
<span class="line"><span>  → AI 交互设计（状态与确认原则）</span></span>
<span class="line"><span>  → 最小可运行 AI Chat UI</span></span>
<span class="line"><span>  → Nuxt 必学路径 →（按需）工具/上传/SSR → 完整项目</span></span>
<span class="line"><span>  →（可选）React / Next 扩展</span></span>
<span class="line"><span>  → 组装配方与自检</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="主路径-自建协议优先" tabindex="-1">主路径：自建协议优先 <a class="header-anchor" href="#主路径-自建协议优先" aria-label="Permalink to &quot;主路径：自建协议优先&quot;">​</a></h2><p>本手册默认：<strong>Nest 产出事件契约，前端按契约消费</strong>（SSE 为主）。<br><code>AI SDK Vue</code> / <code>Vercel AI SDK</code> 是<strong>可选适配层</strong>：仅当团队强制 SDK 或需快速对接兼容后端时再上；上之前先证明自建最小 Chat 已通。</p>`,14)])])}const u=a(r,[["render",i]]);export{g as __pageData,u as default};
